// Builds the Facet registry (one JSON file per item, served by styleguide/api/r/[name].js and\n// installed with the facetui CLI) and showcase/theme.css from:
//   registry/facet/theme/tokens.json  (generated by gen-theme.mjs from Facet tokens)
//   registry/meta/<name>.json          (one per component: title, description, files)
// Dependencies are detected from each file's imports, so meta files only list extras.
import { readFileSync, writeFileSync, readdirSync, existsSync, rmSync, mkdirSync } from "node:fs"
import { join } from "node:path"

const root = new URL("..", import.meta.url).pathname
const pkg = JSON.parse(readFileSync(join(root, "package.json"), "utf8"))
const tokens = JSON.parse(readFileSync(join(root, "registry/facet/theme/tokens.json"), "utf8"))
const STANDARD = new Set(["background","foreground","card","card-foreground","popover","popover-foreground","primary","primary-foreground","secondary","secondary-foreground","muted","muted-foreground","accent","accent-foreground","destructive","border","input","ring","chart-1","chart-2","chart-3","chart-4","chart-5","sidebar","sidebar-foreground","sidebar-primary","sidebar-primary-foreground","sidebar-accent","sidebar-accent-foreground","sidebar-border","sidebar-ring"])

const px = (v) => `${parseFloat(v) / 16}rem`
const light = { radius: px(tokens.radius), ...tokens.light }
const dark = { ...tokens.dark }
// Tailwind colour utilities for the Facet-only colours (the standard names are mapped separately below).
const theme = Object.fromEntries(Object.keys(tokens.light).filter((k) => !STANDARD.has(k)).map((k) => [`color-${k}`, `var(--${k})`]))

// Facet's signature shape: every corner rounded except a tighter top-right.
const corner = (big, small) => `calc(var(--radius) * ${big}) calc(var(--radius) * ${small}) calc(var(--radius) * ${big}) calc(var(--radius) * ${big})`
const css = {
  "@utility rounded-facet-sm": { "border-radius": corner(0.75, 0.25) },
  "@utility rounded-facet": { "border-radius": corner(1, 0.25) },
  "@utility rounded-facet-lg": { "border-radius": corner(1.5, 0.5) },
  "@utility rounded-facet-xl": { "border-radius": corner(2, 0.75) },
  "@utility rounded-facet-2xl": { "border-radius": corner(3, 1) },
  "@keyframes facet-shimmer": { "0%": { "background-position": "200% 0" }, "100%": { "background-position": "-200% 0" } },
  "@keyframes facet-marquee": { from: { transform: "translateX(0)" }, to: { transform: "translateX(calc(-50% - var(--gap, 1rem) / 2))" } },
  "@keyframes facet-caret-blink": { "0%,70%,100%": { opacity: "1" }, "20%,50%": { opacity: "0" } },
}

const metaDir = join(root, "registry/meta")
const metas = readdirSync(metaDir).filter((f) => f.endsWith(".json")).sort().map((f) => JSON.parse(readFileSync(join(metaDir, f), "utf8")))
const typeOf = (p) => (p.startsWith("ui/") ? "ui" : p.startsWith("hooks/") ? "hook" : "lib")
const PEER = new Set(["react", "react-dom"])

const problems = []
const items = metas.map((m) => {
  const deps = new Set(m.dependencies || [])
  const requires = new Set(["theme", ...(m.registryDependencies || []).map((d) => d.replace(/^@facet\//, ""))])
  const files = []
  for (const rel of m.files) {
    const file = join(root, "registry/facet", rel)
    if (!existsSync(file)) { problems.push(`${m.name}: missing file ${rel}`); continue }
    const src = readFileSync(file, "utf8")
    for (const [, spec] of src.matchAll(/from\s+["']([^"']+)["']/g)) {
      if (spec.startsWith("@/registry/facet/ui/")) { const dep = spec.split("/").pop(); if (dep !== m.name) requires.add(dep) }
      else if (spec === "@/registry/facet/lib/utils") requires.add("utils")
      else if (spec === "@/registry/facet/lib/motion") requires.add("motion")
      else if (spec.startsWith("@/")) problems.push(`${m.name}: unsupported import ${spec}`)
      else if (!spec.startsWith(".")) { const pkg = spec.startsWith("@") ? spec.split("/").slice(0, 2).join("/") : spec.split("/")[0]; if (!PEER.has(pkg)) deps.add(pkg) }
    }
    files.push({ path: rel, type: typeOf(rel), content: src })
  }
  return { name: m.name, type: "component", title: m.title, description: m.description, category: m.categories?.[0] ?? "actions", dependencies: [...deps].sort(), requires: [...requires].sort(), files }
})
if (problems.length) { console.error(problems.join("\n")); process.exit(1) }

// Showcase stylesheet with the same values.
const decl = (o) => Object.entries(o).map(([k, v]) => `  --${k}: ${v};`).join("\n")
const block = (sel, body) => `${sel} {\n${Object.entries(body).map(([k, v]) => typeof v === "object" ? `  ${k} { ${Object.entries(v).map(([a, b]) => `${a}: ${b};`).join(" ")} }` : `  ${k}: ${v};`).join("\n")}\n}`
const std = [...STANDARD].map((k) => `  --color-${k}: var(--${k});`).join("\n")
const out = `/* Generated by scripts/sync-registry.mjs — do not edit. */
:root {
${decl(light)}
}
.dark {
${decl(dark)}
}
@theme inline {
${std}
${Object.entries(theme).map(([k, v]) => `  --${k}: ${v};`).join("\n")}
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}
${Object.entries(css).map(([k, v]) => block(k, v)).join("\n")}
`
writeFileSync(join(root, "showcase/theme.css"), out)

// Registry output. The theme item carries the finished stylesheet that `facetui init` puts in the app's CSS.
const outDir = process.argv[2] ? join(process.cwd(), process.argv[2]) : join(root, "../styleguide/api/_registry")
rmSync(outDir, { recursive: true, force: true }); mkdirSync(outDir, { recursive: true })
const lib = (name, title, description, rel, dependencies, requires = []) => ({ name, type: "lib", title, description, dependencies, requires, files: [{ path: rel, type: "lib", content: readFileSync(join(root, "registry/facet", rel), "utf8") }] })
const all = [
  { name: "theme", type: "theme", title: "Facet UI theme", description: "Colour, radius and motion tokens (light + dark), the Tailwind theme mapping and the Facet corner utilities.", dependencies: [], requires: [], css: `@custom-variant dark (&:is(.dark *));\n\n${out.replace(/^\/\*.*\*\/\n/, "")}\n@layer base {\n  * { border-color: var(--border); outline-color: color-mix(in oklab, var(--ring) 50%, transparent); }\n  body { background-color: var(--background); color: var(--foreground); }\n}\n` },
  lib("utils", "cn() helper", "Class name helper (clsx + tailwind-merge) used by every Facet component.", "lib/utils.ts", ["clsx", "tailwind-merge"]),
  lib("motion", "Facet motion presets", "Springs, easings and variants shared by every Facet component, plus <FacetMotion> for reduced-motion support.", "lib/motion.tsx", ["motion"], ["theme"]),
  ...items,
  { name: "all", type: "bundle", title: "Everything", description: "Every Facet UI React component in one command.", dependencies: [], requires: items.map((i) => i.name) },
  // Code shown in the style guide once a buyer unlocks it (not installable).
  { name: "docs-snippets", type: "docs", title: "Style guide code", description: "React markup for every style guide component page.", ...JSON.parse(readFileSync(join(root, "registry/docs-snippets.json"), "utf8")) },
]
for (const it of all) writeFileSync(join(outDir, `${it.name}.json`), JSON.stringify(it) + "\n")
writeFileSync(join(outDir, "index.json"), JSON.stringify({ name: "facet", version: pkg.version, items: all.filter((it) => it.type !== "docs").map(({ name, type, title, description, category }) => ({ name, type, title, description, ...(category ? { category } : {}) })) }) + "\n")
console.log(`registry: ${all.length} items (${items.length} components) -> ${outDir}`)
